const fs = require('fs');
const path = require('path');
const vm = require('vm');
const root = path.resolve(__dirname, '..');
function load(rel){
  const filename = path.join(root, rel);
  vm.runInThisContext(fs.readFileSync(filename,'utf8'), {filename});
}
function write(rel, name, value){
  const out = path.join(root, rel);
  fs.writeFileSync(out, `/* generated by scripts/bundle_runtime.js */\nwindow.${name}=${JSON.stringify(value)};\n`);
}

global.window = {};
for(const f of ['data/data.js','data/extra.js','data/v05.js','data/v060.js','data/v061.js']) load(f);
write('data/data_bundle.js','DOT_DATA',window.DOT_DATA);

global.window = {};
for(const f of ['data/i18n.js','data/i18n_extra.js','data/i18n_v05.js','data/i18n_v058.js','data/i18n_v060.js','data/i18n_v061.js','data/i18n_v062.js','data/i18n_v065.js']) load(f);
write('data/i18n_bundle.js','DOT_I18N',window.DOT_I18N);

console.log('Generated data/data_bundle.js and data/i18n_bundle.js');
